const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([39.4769, 13.4969]).buffer(10000); // Mekele, Ethiopia, 10km buffer
  const startPeriod = {
    start: '1984-01-01',
    end: '1987-12-31',
    label: '1984-1987'
  };
  const endPeriod = {
    start: '2022-01-01',
    end: '2024-12-31',
    label: '2022-2024'
  };
  const URBAN_THRESHOLD = 0; // NDBI > 0 is a common threshold for urban areas

  // 2. Data Acquisition & Processing Functions
  const cloudMaskL457 = (image) => {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
    return image.updateMask(cloud.not());
  };

  const cloudMaskL89 = (image) => {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
    return image.updateMask(cloud.not());
  };

  const calculateNDBI_L5 = (image) => {
    return image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
  };

  const calculateNDBI_L89 = (image) => {
    return image.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');
  };

  // 3. Process Early Period
  let collection1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(startPeriod.start, startPeriod.end);

  if (collection1.size().getInfo() === 0) {
    console.log(`No Landsat 5 images found for ${startPeriod.label}.`);
    console.log('A');
    return;
  }

  const image1 = collection1.map(cloudMaskL457)
    .map(calculateNDBI_L5)
    .median()
    .clip(aoi);

  const urban1 = image1.gt(URBAN_THRESHOLD);
  const urbanArea1 = urban1.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  // 4. Process Late Period
  let collection2 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .merge(ee.ImageCollection('LANDSAT/LC08/C02/T1_L2'))
    .filterBounds(aoi)
    .filterDate(endPeriod.start, endPeriod.end);

  if (collection2.size().getInfo() === 0) {
    console.log(`No Landsat 8/9 images found for ${endPeriod.label}.`);
    console.log('C1');
    return;
  }

  const image2 = collection2.map(cloudMaskL89)
    .map(calculateNDBI_L89)
    .median()
    .clip(aoi);

  const urban2 = image2.gt(URBAN_THRESHOLD);
  const urbanArea2 = urban2.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  // 5. Validation & Final Answer
  const urbanSqKm1 = ee.Number(urbanArea1.get('NDBI')).divide(1e6).getInfo();
  const urbanSqKm2 = ee.Number(urbanArea2.get('NDBI')).divide(1e6).getInfo();

  if (urbanSqKm1 === null || urbanSqKm2 === null) {
      console.log('Calculation failed: could not compute urban area for one or both periods.');
      console.log('C3');
      return;
  }

  if (urbanSqKm1 === 0 || urbanSqKm2 === 0) {
      console.log('No valid urban pixels found after processing for one or both periods.');
      console.log(`Urban Area (${startPeriod.label}): ${urbanSqKm1.toFixed(2)} sq km`);
      console.log(`Urban Area (${endPeriod.label}): ${urbanSqKm2.toFixed(2)} sq km`);
      console.log('C2');
      return;
  }

  console.log(`Urban Area (${startPeriod.label}): ${urbanSqKm1.toFixed(2)} sq km`);
  console.log(`Urban Area (${endPeriod.label}): ${urbanSqKm2.toFixed(2)} sq km`);

  if (urbanSqKm2 > urbanSqKm1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('D');
});
